+              "</section>" +
+            "</div>" +
+          "</main>"
+        );
+      }
+
+      function App() {
+        return SupportPage();
+      }
+
+      document.getElementById("app").innerHTML = App();
+
+      var form = document.getElementById("support-form");
+      var statusMessage = document.getElementById("form-status");
+      var fieldConfig = {
+        "full-name": {
+          helperId: null,
+          validate: function (value) {
+            return value.trim() ? "" : "Error: Enter your full name.";
+          }
+        },
+        "email-address": {
+          helperId: null,
+          validate: function (value) {
+            var trimmedValue = value.trim();
+            if (!trimmedValue) {
+              return "Error: Enter your email address.";
+            }
+
+            return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmedValue)
+              ? ""
+              : "Error: Enter a valid email address, like name@example.com.";
+          }
+        },
+        "phone-number": {
+          helperId: "phone-number-helper",
