+            if (!trimmedValue) {
+              return "";
+            }
+
+            return /^[+]?\d[\d\s().-]{6,}$/.test(trimmedValue)
+              ? ""
+              : "Error: Enter a phone number in the format +1 555-123-4567.";
+          }
+        }
+      };
+      var hasSubmitted = false;
+
+      function updateDescriptions(inputId, hasError) {
+        var describedBy = [];
+        var config = fieldConfig[inputId];
+
+        if (config.helperId) {
+          describedBy.push(config.helperId);
+        }
+
+        if (hasError) {
+          describedBy.push(inputId + "-error");
+        }
+
+        var input = document.getElementById(inputId);
+        if (describedBy.length > 0) {
+          input.setAttribute("aria-describedby", describedBy.join(" "));
+        } else {
+          input.removeAttribute("aria-describedby");
+        }
+      }
+
+      function setFieldError(inputId, message) {
+        var input = document.getElementById(inputId);
+        var errorElement = document.getElementById(inputId + "-error");
+        var hasError = Boolean(message);
+
+        input.setAttribute("aria-invalid", hasError ? "true" : "false");
+        errorElement.hidden = !hasError;
+        errorElement.textContent = message;
+        updateDescriptions(inputId, hasError);
+      }
+
+      function validateField(inputId) {
+        var input = document.getElementById(inputId);
+        var message = fieldConfig[inputId].validate(input.value);
+        setFieldError(inputId, message);
+        return message;
+      }
+
+      Object.keys(fieldConfig).forEach(function (inputId) {
+        var input = document.getElementById(inputId);
+
+        updateDescriptions(inputId, false);
+
+        input.addEventListener("blur", function () {
+          if (hasSubmitted || input.value.trim()) {
+            validateField(inputId);
+          }
+        });
+
+        input.addEventListener("input", function () {
+          if (hasSubmitted || input.getAttribute("aria-invalid") === "true") {
+            validateField(inputId);
+          }
+        });
+      });
+
+      form.addEventListener("submit", function (event) {
+        event.preventDefault();
+        hasSubmitted = true;
+        statusMessage.textContent = "";
+
+        var firstInvalidField = null;
+
+        Object.keys(fieldConfig).forEach(function (inputId) {
+          var errorMessage = validateField(inputId);
+          if (!firstInvalidField && errorMessage) {
+            firstInvalidField = document.getElementById(inputId);
+          }
+        });
+
+        if (firstInvalidField) {
+          firstInvalidField.focus();
+          return;
+        }
+
+        statusMessage.textContent = "Demo form ready: all fields passed validation.";
+      });
+    </script>
+  </body>
+</html>
*** End Patch
